UPDATE cmn.cd_dtl 
    cd_nm=#{row.cd_nm},sort_seq=#{row.sort_seq},
    use_yn=#{row.use_yn},attr1_val=#{row.attr1_val},
    attr2_val=#{row.attr2_val},attr3_val=#{row.attr3_val},
    aply_bgn_dt=#{row.aply_bgn_dt},updated_at=#{now},updated_by=#{actor}
     WHERE cd_grp_id=#{group} AND dtl_cd=#{row.dtl_cd}

