INSERT INTO cmn.oprt_std(oprt_std_id,aply_bgn_ym,oprt_std_nm,num_val,txt_val,unit_nm,use_plc_desc,oprt_std_desc,created_by)
    SELECT oprt_std_id,#{month},oprt_std_nm,#{value.num_val},#{value.txt_val},unit_nm,use_plc_desc,oprt_std_desc,#{actor} FROM cmn.oprt_std WHERE oprt_std_id=#{source.oprt_std_id} AND aply_bgn_ym=#{source.aply_bgn_ym}
    ON CONFLICT(oprt_std_id,aply_bgn_ym) DO UPDATE SET num_val=EXCLUDED.num_val,txt_val=EXCLUDED.txt_val
